from pathlib import Path
import json, re
ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'content/course-plan-v2'
units=[]; lessons=[]
def unit(id,title,pages,coverageNote=''):
    term='upper' if id.startswith('U') else 'lower'
    units.append(dict(id='G3-'+id,term=term,title=title,sourceId='G3-'+term,printedPages=pages,coverage=[],sequence=[],notes=coverageNote))
def add(code,title,pages,objective,problem,why,model,explain,example,practice,wrong,correction,retell,next,pre='',kind=None):
    uid,tag=code.split('-'); tier=tag[0]
    u=[x for x in units if x['id']=='G3-'+uid][0]
    nums=[int(n) for n in re.findall(r'\d+',pages)]
    pp='–'.join(str(n+6) for n in nums)
    prior=u['sequence'][-1:]
    item=dict(id='G3-'+code,title=title,unitId=u['id'],tier=tier,minutes=35,
      anchor=dict(sourceId=u['sourceId'],printedPages=pages,pdfPages=pp,type=kind or ('textbook' if tier in 'BR' else 'extension'),note='原创教案；页码锚定相关教材内容，不表示本教案题目出自教材。'+('本课作相关内容的提升，超出教材直接要求部分见讲解边界。' if tier in 'EO' else '')),
      prerequisites=[pre] if pre else ['本单元前一基础课；首次学习时先用实物确认相关数与形经验'],dependsOn=prior,
      objective=objective,realProblem=problem,why=why,model=model,explanation=explain.split('｜'),
      example=dict(question=example[0],steps=example[1].split('｜'),answer=example[2]),
      practice=[dict(zip(['level','question','answer','reason'],p.split('|'))) for p in practice],
      misconception=dict(wrong=wrong,correction=correction),retell=retell,next=next)
    lessons.append(item);u['sequence'].append(item['id']);u['coverage'].append(dict(topic=title,lessons=[item['id']]))

unit('U01','观察物体','1–5','正面、侧面、上面观察；单一视图信息不足；剪展纸盒。')
add('U01-B01','换一个位置，看到的样子为什么变了','1–2','能说清观察位置与所见面的对应。','给玩具汽车拍照片，车头照与侧面照看起来不同，怎样告诉别人自己站在哪里？','照片只保留朝向观察者的部分；视图变化并不代表物体改变。','把长方体橡皮盒放稳，前面贴红点、右面贴蓝点、上面贴星星；只移动人。','固定盒子，依次从前、右、上观察。｜记录看见的标记与面的形状。｜对比三次：物体没动，观察方向变了。',('盒子前面有红点，右面有蓝点。Kevin只想拍到蓝点所在面的正面，应从哪里拍？','先找蓝点在哪个面。｜让镜头正对右面，而不是转动盒子。','从盒子的右侧正对蓝点拍。'),['基础|固定盒子前面是红点，从前面正对着看见哪个标记？|红点|视线正对前面。','基础|桌面上的盒子，上面贴星星。站高往下看主要看见哪个标记？|星星|从上向下看上面。','变式|人从盒子前面走到右面，盒子没有动。变的是物体还是观察方向？|观察方向|不能把视图变化说成物体变形。','变式|只写“我看见一个长方形”，能确定站在盒子哪边吗？|通常不能|不同面可能都为长方形。','迁移|要让没见过玩具车的人了解车头和两侧，拍一张车头照够吗？|不够，可补两侧照片|一张照片未提供所有方向的信息。','挑战|一个球表面没有标记，从不同方向看都像圆。能仅靠轮廓判断相机方向吗？|不能|球的这些视图相同。'],'看到不同形状，说明盒子变形了。','先固定物体，再比较观察方向。','向别人解释为什么三张照片可以属于同一个盒子。','接着研究：一张照片能不能唯一确定物体。','能辨认长方体、正方体、球、圆柱；不要求画三视图。')
add('U01-B02','看见一个面，能猜出整个物体吗','2–3','知道线索可能不足，能提出补充观察。','一张照片只显示一个正方形，包裹一定是正方体吗？','判断要看证据是否足够；同一平面形状可能来自不同立体物体。','比较正方体与端面为正方形的长盒子；只露出端面再打开遮挡。','先列至少两个符合照片的物体。｜找能区分它们的方向。｜用新观察排除不合条件的猜测。',('物体正面是正方形。从右侧看是一个很长的长方形。它可能是正方体吗？','正方体各面都是同样大的正方形。｜右侧是非正方形的长方形，与此冲突。','不是正方体，可以是有正方形端面的长方体。'),['基础|只看到圆形正面，物体一定是球吗？|不一定|圆柱的底面也可能是圆。','基础|正方体任意一个面是什么形状？|正方形|这是正方体面的特征。','变式|正面是正方形、侧面是长方形的盒子，与所有面相同的正方体相同吗？|不同|侧面信息已经区分两者。','变式|一个杯子的照片没拍到把手，能断定它没有把手吗？|不能|把手可能在背面。','迁移|卖家只发了鞋盒顶面的照片，你还想了解盒子高不高，应补哪张照片？|正面或侧面|这些方向能显示高度。','挑战|两件物体从正面看相同，从上面看不同，“正面相同就相同”哪里错？|把部分信息当成全部信息|一个反例即可否定该判断。'],'正面一样，物体一定一样。','多看一个方向可能排除一种猜测，但不能无条件声称已唯一确定。','你会怎样向Kevin证明“看见正方形”不等于“找到正方体”？','四上与五年级组合体视图会在此基础上增加层数和隐藏方块。','G3-U01-B01 的视角经验。')
add('U01-B03','把纸盒打开，六个面去了哪里','3–5','能在展开的纸盒上追踪相邻面，并实际验证折回。','要给一个盒子的六个面分别贴图案，怎样避免把相邻图案贴到相反位置？','展开把空间关系变成平面关系，折回可以检查推测。','使用一个真实小长方体纸盒，六面标A到F；沿边剪开且各面保持相连，不依赖缺失插图。','先在盒子上标前后左右上下。｜展开后追踪同一个面，保留邻接边。｜折回核对；平面上离得远不代表折回后不相邻。',('在正方体纸盒上，上面贴星星、下面贴圆点。展开再折回，星星面会和圆点面共用一条边吗？','上下是相对面。｜只剪开再按原样折回，没有改变相对关系。','不会，两面仍相对。'),['基础|长方体纸盒共有几个面？|6个|展开前后面数不变。','基础|只展开不裁掉纸，纸的总面积会改变吗？|不会|这里只改变摆放方式。','变式|展开图里两个面挨着并共享原来的边，折回后还相邻吗？|相邻|共用边没有剪断。','变式|展开图里不相邻的面，折回后一定不相邻吗？|不一定|折叠可使原来分开的边接上。','迁移|给盒子前面和后面贴不同颜色，如何验证没贴错？|先标记面，折回核对前后相对|要用空间关系检查。','挑战|剪开一个正方体盒子，要求六面仍连成一片。随便剪五条边一定能摊平吗？|不能保证|能否摊平需检查剩余连接，不能只数剪了几条。'],'展开图的样子一变，六个面就变了。','面与原来的标记仍是一一对应，空间关系靠折回检查。','讲出一个必须折回盒子才容易确认的判断。','五下体积与表面积再做精确面积计算；本课不背11种正方体展开图。','G3-U01-B01；安全使用纸盒和剪刀。')

unit('U02','混合运算','6–19','正文例1–6、两步数量关系、整理与关联练习；去添括号提升有教材比较题依据。')
add('U02-B01','一串加减或乘除，按什么顺序算','6–7','能识别同一级运算，并从左往右计算。','车上有28人，先下车9人，再上车6人；想在一行里记录变化。','共同的读法让一串算式不会被每个人读成不同的意思。加减同级，乘除同级。','把每一步人数写在连续三张卡片上；另用24个棋子先分6组再把每组取2倍。','28−9+6按发生顺序连接，等于19+6。｜24÷6×2从左往右得到4×2；不是先乘。｜每写一行保留还未计算的部分，等号表示前后相等。',('计算48÷8×3，并解释为什么不先算8×3。','只有乘除，同级从左往右。｜48÷8=6，6×3=18。','18；先乘会把原式改成48÷(8×3)。'),['基础|算35−12+8。|31|先35−12=23，再加8。','基础|算36÷6×2。|12|先除再乘。','变式|算5×8÷4。|10|40÷4=10。','变式|有人把40−18+2算成20。他可能把哪一步放在了前面？|先算18+2|这样实际算了40−(18+2)。','迁移|书架有42本书，借出15本又归还7本，写一条算式。|42−15+7=34（本）|变化顺序先减后加。','挑战|18÷3×2和18÷(3×2)结果相同吗？|不相同，分别12和3|括号改变被除的组。'],'乘法永远比除法先算，加法永远比减法先算。','乘除同一级；加减同一级；同级从左往右。','用36÷6×2说明“先乘除”中的乘和除谁先谁后。','下一课加入不同级运算，再引入括号。','表内乘除、两步加减。')
add('U02-B02','先算乘除：先数清一整组','7–8','能把等量组和零散数量写成混合算式。','有3盒彩笔，每盒6支，另有4支散装彩笔，一共有几支？','乘法把一整组数量打包；先算组的总量，才能与散装数量合并。顺序规则与情境结构相符。','画3个框，每框6点，框外4点；框内总数对应3×6。','指出4与3分别表示什么，不能把不同意义的数先合并。｜4+3×6先算乘法，得到4+18。｜出现除法时同理先求每组或份数；最后进行加减。',('24颗珠子每6颗装一袋，另外已有3袋，一共多少袋？','24÷6=4袋。｜4+3=7袋，合式为24÷6+3。','7袋。'),['基础|7+4×5等于多少？|27|先算4×5=20。','基础|30−18÷3等于多少？|24|先18÷3=6。','变式|8+12÷4中，哪一部分先看作一个数量？|12÷4|先得到商，再与8相加。','变式|“2盒彩笔每盒8支，另有5支”能写成(2+5)×8吗？|不能，应2×8+5|5是支数，不是盒数。','迁移|3张成人票每张9元，再买1张5元儿童票，应付多少？|3×9+5=32元|同类票价先求和。','挑战|6+3×4和(6+3)×4的差是多少？|18|前式18，后式36，多乘了另外3个6。'],'凡是从左开始算总是对的。','先确定层级，再在同级内从左往右。','用“盒”和“支”解释为什么不能把2和5先相加。','接着研究情境要求先加或减时，怎样用括号写清楚。','G3-U02-B01。')
add('U02-B03','括号把需要先做的事圈在一起','8–11','能按情境添加括号，并正确读取括号内外的含义。','两个盒子分别有18颗和12颗珠子，把所有珠子每6颗装一袋，可以装几袋？','不加括号，18+12÷6会把第一盒珠子当作已经装好的袋数；括号明确先求总颗数。','画两堆珠子，用大框同时包住两堆，再从总堆每6颗圈一袋。','先用两条算式表达动作。｜用括号把第一步的整个结果放进第二步。｜括号内若也含多种运算，仍遵守乘除先于加减；本课先练一层小括号。',('把18颗与12颗珠子合并，每6颗一袋，有几袋？','先合并18+12=30颗。｜30÷6=5袋，写成(18+12)÷6。','5袋。'),['基础|(15+9)÷6等于多少？|4|先24再除6。','基础|50−(12+8)等于多少？|30|括号总共是20。','变式|50−(12−8)等于多少？|46|括号是4，不能把加减号看漏。','变式|给6+4×3添一对括号，使结果为30。|(6+4)×3|把10作为每组数乘3。','迁移|有40元，买一本16元的书，剩下的钱每3元买一支笔，可买几支？|(40−16)÷3=8支|先求剩余的钱。','挑战|同样是24÷4+2，添括号后能得到4吗？|能：24÷(4+2)=4|除数变成整体6。'],'见到括号就可以删掉，数没有变。','数没变不等于运算结构没变；先读括号表示的整个数量。','把(18+12)÷6讲成完整故事，再说明18+12÷6为什么不是同一件事。','下两课从文字和线段图主动构造算式。','G3-U02-B02。')
add('U02-B04','同一个“剩多少”，可以怎样列式','12–13','能用逐次减与先合并再减表示同一情境。','60张卡片，上午送出14张，下午送出16张，还剩多少？','两批互不重叠的送出量可以先合并；这种数量关系是去添括号的依据。','一条60格纸带标出14格、16格与剩余部分，三段刚好拼回整体。','逐次减：60−14−16。｜先求共送出30，再60−(14+16)。｜把送出的两段加回剩余，检查是否回到60。',('60张卡片分两次送出14张和16张。用两种方法求剩余。','60−14−16=46−16=30。｜60−(14+16)=60−30=30。','30张；两式描述同一组互不重叠的送出。'),['基础|80本书先借出23本，再借出17本，还剩多少？|40本|80−23−17=40。','基础|把80−23−17写成“先求一共借出”。|80−(23+17)|括号内要相加。','变式|80−(23+17)能改成80−23+17吗？|不能|第二批也是借出，不是归还。','变式|原有50张，送出8张又收到12张，还能把8与12合起来一起减吗？|不能|两次变化方向不同。','迁移|一条90厘米纸带，剪去不重叠的25厘米和35厘米，剩多少？|30厘米|两段合为60厘米。','挑战|总数是90，已送出两批共58，剩下32。只知道这些，能求第一批多少吗？|不能|两批的分配还不确定。'],'只要看到两个数，就可以随便合并。','先判断它们是否表示同一种量、是否都要从总数扣除。','为什么60−(14+16)展开后是两个减号？','提升课会讨论括号里是差时，为什么后一个符号反而改变。','G3-U02-B03。')
add('U02-B05','两步问题：先找到缺少的那个数量','13–17','能从目标倒找所需数量，区分求差后乘与分别相除后求差。','小林做9朵花，小乔比小林少3朵，小安做的是小乔的2倍。怎样算小安的花数？','第二步用的是小乔的数量，而不是题目中最先出现的9；读清关系比关键词配运算重要。','画9格与少3格的纸带，再把较短纸带复制成2段；另用等长每袋单位比较两堆。','先问最后要求谁，再找该数量依赖谁。｜用中间问题“先求小乔做几朵”连接两步。｜比较另一结构：(48−24)÷6与48÷6−24÷6在整除情境中等价。',('红珠子48颗、蓝珠子24颗，每6颗同色珠子装一袋。红袋比蓝袋多几袋？','红8袋，蓝4袋，差4袋。｜也可先求多出的24颗，再24÷6=4袋。','多4袋。'),['基础|小乔比9朵少3朵，是几朵？|6朵|先求比较对象。','基础|小安做的是6朵的2倍，是几朵？|12朵|6×2。','变式|“比9少3的数的2倍”写成9−3×2对吗？|不对，应(9−3)×2|先求差，后求倍数。','变式|36颗与12颗分别每6颗装袋，袋数相差多少？|4袋|36÷6−12÷6=6−2。','迁移|两卷绳子长42米和30米，都截成6米一段，长卷多几段？|2段|差12米正好2段。','挑战|若两堆都每6颗装满袋，剩余不装袋，10颗和5颗袋数相差多少？能直接(10−5)÷6吗？|相差1袋，不能用该式直接求满袋差|涉及余数取整，两堆的满袋规则要分别处理。'],'所有“差÷每份数”都能替代分别装满袋再求差。','无余数的等量分组可直接迁移；有剩余只数满袋时先检查限制。','你怎样从“最后问什么”找到必须先算的中间数量？','归一、归总正式放在三下除法章；此处只建立两步结构。','G3-U02-B03；整除的等量分组。')
add('U02-E01','去掉或添上括号，怎样保证数量不变','12–19','解释a−(b+c)、a−(b−c)以及加号后括号的去添规则，用正整数实例理解。','有70元，支付一件标价28元、优惠8元的物品。怎么写实付后剩余的钱？','减去的是实际花的钱28−8；若先扣28，就要把没有花掉的8加回来。','把70元余额条分成实付20与余款50；对照“先扣28再退8”。','70−(28−8)=70−28+8；多扣了8，要补回。｜70−(28+8)=70−28−8；两笔都扣除。｜加号后把内部加减顺序保留；添括号是反向操作。限制先用中间量非负的例子，字母通式四年级再系统写。',('计算70−(28−8)，再写一个等值的无括号式。','括号内28−8=20，70−20=50。｜无括号式70−28+8=42+8=50。','50；等值式为70−28+8。'),['基础|60−(14+6)去括号后怎么写？|60−14−6|两个量都扣除。','基础|60−(14−6)去括号后怎么写？|60−14+6|先多扣6，需要补回。','变式|25+(18−7)去括号后怎么写？|25+18−7|增加净数量11，与先加18再减7相同。','变式|60−14+6把后两项放入括号，应写什么？|60−(14−6)|括号表示净扣除8。','迁移|80元先买30元的票，退回5元优惠。余款有两种写法吗？|80−30+5=80−(30−5)=55元|实际花25元。','挑战|有人说“去括号就是把里面的符号全变”。用一个例子驳倒。|如10+(6−2)=10+6−2=14，不是10−6+2|要看括号前的运算，不能一律变号。'],'去括号后，所有符号都反过来。','加号后内部加减不变；减号后内部加减互换。这里只处理括号内加减，不套到乘法上。','不说“口诀规定”，用退优惠的钱解释70−(28−8)为什么出现+8。','四下运算律章系统整理与简便计算；同一基础内容届时诊断通过即可跳过。','G3-U02-B04；能解释两步同量关系。')
add('U02-E02','连续除与括号里的乘除，为什么有关联','19；三下28–30','用具体整除例子区分a÷b÷c与a÷(b÷c)，不把除法当成结合律。','48张卡先平分给6组，每组再平分给2人。每人分到几张？','每人属于全部6×2个人之一，所以连除可合成除以人数的乘积；这不是随意挪动括号。','画6组、每组2人，共12个相等份；再比较只分给6÷2=3组的另一情境。','48÷6÷2=4，对应48÷(6×2)。｜48÷(6÷2)=16，对应48÷6×2。｜乘号与除号的变化取决于分组含义；本课限定正整数与各步整除，不能除以0。',('48张卡先分6组、每组2人，每人多少张？若改成48÷(6÷2)，还表示同一分法吗？','总人数6×2=12，每人4张。｜6÷2=3，48÷3=16，代表只分3份。','4张；另一个式子是16，不是同一分法。'),['基础|72÷8÷3等于多少？|3|9÷3=3。','基础|72÷(8×3)与上式结果相同吗？|相同，都是3|总分为24份。','变式|72÷(8÷2)等于多少？|18|除数是4。','变式|72÷8×2应添成72÷(8×2)吗？|不应，应为72÷(8÷2)|原式18，错误改式4.5；本课只用整除结果时也能判不等。','迁移|96本练习本平分4班，每班再分给3组，每组多少？|96÷4÷3=8本|共12组。','挑战|“除法也有结合律”，用48、6、2说明哪里错。|(48÷6)÷2=4，但48÷(6÷2)=16|加括号的位置改变除数的意义。'],'只要三个数和两个除号一样，括号随便放。','连续除等于除以除数的积，不等于把两个除数先相除。','画出“6组每组2人”和“6÷2组”有什么不同。','三下连除情境再次迁移；四下形成简便运算系统，不重复首教。','G3-U02-B03；表内乘除。')
add('U02-O01','从算错的结果倒着找回去','19','能沿运算流程逆推未知数并检验，不依赖猜口诀。','原式是7+□×4，小乐先算加法再乘法，错误结果得到44。方框里是什么？','错误结果仍包含信息；把每个实际做过的动作倒着撤销，就能还原。','流程图：□→加7→乘4→44；逆向箭头标除4、减7。','先写出他实际算的是(7+□)×4。｜由44÷4=11，再11−7=4。｜把4代回正确原式7+4×4，求正确结果并检查错误路线。',('7+□×4被误算为(7+□)×4，结果44。求□及正确结果。','44÷4=11，11−7=4。｜正确7+4×4=23；错误(7+4)×4=44，核对通过。','□=4，正确结果23。'),['基础|一个数先加5得12，原数多少？|7|撤销加5用减5。','基础|一个数乘3得27，原数多少？|9|撤销乘3用除3。','变式|一个数先加2再乘5得35，原数多少？|5|35÷5−2=5。','变式|有人从35先减2再除5，倒推哪里错？|撤销顺序反了|最后做乘5，必须先除5。','迁移|3+□×6被误算成(3+□)×6，得48。正确结果多少？|33|□=48÷6−3=5，3+5×6=33。','挑战|□−4再乘3得18，与□×3再减4得18，是同一道问题吗？|不是，前者□=10，后者不是整数|动作顺序不同；可先用前者10代回后者得26验证不等。'],'逆向推理就是把运算符号改掉，顺序不用变。','要从最后一步开始，一步一步撤销，并代回检查。','把这道错题的两条流程讲清：他怎样算错，你怎样还原。','四年级逆向数量关系与五年级方程将用另一种语言表达同一关系。','G3-U02-B01至B05；本课可选。')
